import{_ as l,a0 as r,w as s,s as m,I as e,x as n,ao as p,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"LFCS 系列第五讲：如何在 Linux 中挂载/卸载本地文件系统和网络文件系统（Samba 和 NFS） | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第五讲：如何在 Linux 中挂载/卸载本地文件系统和网络文件系统（Samba 和 NFS） | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第五讲：如何在 Linux 中挂载/卸载本地文件系统和网络文件系统（Samba 和 NFS） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第五讲：如何在 Linux 中挂载/卸载本地文件系统和网络文件系统（Samba 和 NFS） | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 5 - LFCS--How to Mount or Unmount Local and Network Samba and NFS Filesystems in Linux","title":"LFCS 系列第五讲：如何在 Linux 中挂载/卸载本地文件系统和网络文件系统（Samba 和 NFS）","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 5 - LFCS--How to Mount or Unmount Local and Network Samba and NFS Filesystems in Linux.md","filePath":"[post].md"}'),u={name:"LFCS/Part 5 - LFCS--How to Mount or Unmount Local and Network Samba and NFS Filesystems in Linux.md"};function d(S,t,b,f,w,x){const a=r("Link");return s(),m("div",null,[t[21]||(t[21]=e("h1",{id:"lfcs-系列第五讲-如何在-linux-中挂载-卸载本地文件系统和网络文件系统-samba-和-nfs",tabindex:"-1"},[n("LFCS 系列第五讲：如何在 Linux 中挂载/卸载本地文件系统和网络文件系统（Samba 和 NFS） "),e("a",{class:"header-anchor",href:"#lfcs-系列第五讲-如何在-linux-中挂载-卸载本地文件系统和网络文件系统-samba-和-nfs","aria-label":"Permalink to “LFCS 系列第五讲：如何在 Linux 中挂载/卸载本地文件系统和网络文件系统（Samba 和 NFS）”"},"​")],-1)),t[22]||(t[22]=e("p",null,"Linux 基金会已经发起了一个全新的 LFCS（Linux Foundation Certified Sysadmin，Linux 基金会认证系统管理员）认证，旨在让来自世界各地的人有机会参加到 LFCS 测试，获得关于有能力在 Linux 系统中执行中间系统管理任务的认证。该认证包括：维护正在运行的系统和服务的能力、全面监控和分析的能力以及何时向上游团队请求支持的决策能力。",-1)),t[23]||(t[23]=e("p",null,[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/10/lfcs-Part-5.png",alt:"Linux Foundation Certified Sysadmin – Part 5"})],-1)),t[24]||(t[24]=e("p",null,[e("em",null,"LFCS 系列第五讲")],-1)),t[25]||(t[25]=e("p",null,"请看以下视频，这里边介绍了 Linux 基金会认证程序。",-1)),t[26]||(t[26]=e("p",null,"注：youtube 视频",-1)),t[27]||(t[27]=e("iframe",{width:"720",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"//www.youtube.com/embed/Y29qZ71Kicg"},null,-1)),t[28]||(t[28]=p(`<p>本讲是系列教程中的第五讲，在这一讲里边，我们会解释如何在 Linux 中挂载/卸载本地和网络文件系统。这些都是 LFCS 认证中的必备知识。</p><h3 id="挂载文件系统" tabindex="-1">挂载文件系统 <a class="header-anchor" href="#挂载文件系统" aria-label="Permalink to “挂载文件系统”">​</a></h3><p>在个硬盘分好区之后，Linux 需要通过某些方式对硬盘分区上的数据进行访问。Linux 并不会像 DOS 或者 Windows 那样给每个硬盘分区分配一个字母来作为盘符，而是将硬盘分区挂载到统一的目录树上的挂载点。</p><p>挂载点是一个目录，挂载是一种访问分区上文件系统的方法，挂载文件系统实际上是将一个确切的文件系统（比如一个分区）和目录树中指定的目录联系起来的过程。</p><p>换句话说，管理存储设备的第一步就是把设备关联到文件系统树。要完成这一步，通常可以这样：用 mount 命令来进行临时挂载（用完的时候，使用 umount 命令来卸载），或者通过编辑 /etc/fstab 文件之后重启系统来永久性挂载，这样每次开机都会进行挂载。</p><p>不带任何选项的 mount 命令，可以显示当前已挂载的文件系统。</p><pre><code># mount
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/check-mounted-filesystems.png" alt="Check Mounted Filesystem in Linux"></p><p><em>检查已挂载的文件系统</em></p><p>另外，mount 命令通常用来挂载文件系统。其基本语法如下：</p><pre><code># mount -t type device dir -o options
</code></pre><p>该命令会指引内核将在设备上找到的文件系统（如已格式化为指定类型的文件系统）挂载到指定目录。像这样的形式，mount 命令不会再到 /etc/fstab 文件中进行确认。</p><p>除非像下面，挂载指定的目录或者设备：</p><pre><code># mount /dir -o options
或
# mount device -o options
</code></pre><p>mount 命令会尝试寻找挂载点，如果找不到就会查找设备（上述两种情况下，mount 命令会在 /etc/fstab 查找相应的设备或挂载点），最后尝试完成挂载操作（这个通常可以成功执行，除非你的挂载点或者设备正在使用中，或者你调用 mount 命令的时候没有 root 权限）。</p><p>你可以看到，mount 命令的每行输出都是如下格式：</p><pre><code>device on directory type (options)
</code></pre><p>例如：</p><pre><code>/dev/mapper/debian-home on /home type ext4 (rw,relatime,user_xattr,barrier=1,data=ordered)
</code></pre><p>读作：</p><p>设备 dev/mapper/debian-home 挂载在 /home 下，它被格式化为 ext4，并且有以下挂载选项： rw，relatime，user_xattr，barrier=1，data=ordered。</p><p><strong>mount 命令选项</strong></p><p>下面列出 mount 命令的常用选项</p><ul><li>async：允许在将要挂载的文件系统上进行异步 I/O 操作</li><li>auto：标示该文件系统通过 mount -a 命令挂载，与 noauto 相反。</li><li>defaults：该选项相当于 <code>async,auto,dev,exec,nouser,rw,suid</code> 的组合。注意，多个选项必须由逗号隔开并且中间没有空格。倘若你不小心在两个选项中间输入了一个空格，mount 命令会把后边的字符解释为另一个参数。</li><li>loop：将镜像文件（如 .iso 文件）挂载为 loop 设备。该选项可以用来模拟显示光盘中的文件内容。</li><li>noexec：阻止该文件系统中可执行文件的执行。与 exec 选项相反。</li><li>nouser：阻止任何用户（除 root 用户外） 挂载或卸载文件系统。与 user 选项相反。</li><li>remount：重新挂载文件系统。</li><li>ro：只读模式挂载。</li><li>rw：读写模式挂载。</li><li>relatime：只要访问时间早于修改时间，就更新文件的的访问时间。</li><li>user_xattr：允许用户设置和移除可扩展文件系统属性。</li></ul><p><strong>以 ro 和 noexec 模式挂载设备</strong></p><pre><code># mount -t ext4 /dev/sdg1 /mnt -o ro,noexec
</code></pre><p>在本例中，我们可以看到，在挂载点 /mnt 中尝试写入文件或者运行可执行文件都会显示相应的错误信息。</p><pre><code># touch /mnt/myfile
# /mnt/bin/echo “Hi there”
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-Device-Read-Write.png" alt="Mount Device in Read Write Mode"></p><p><em>可读写模式挂载设备</em></p><p><strong>以默认模式挂载设备</strong></p><p>以下场景，我们在重新挂载设备的挂载点中，像上例一样尝试你写入文件和运行可执行文件。</p><pre><code># mount -t ext4 /dev/sdg1 /mnt -o defaults
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-Device.png" alt="Mount Device in Linux"></p><p><em>挂载设备</em></p><p>在这个例子中，我们发现写入文件和命令都完美执行了。</p><h3 id="卸载设备" tabindex="-1">卸载设备 <a class="header-anchor" href="#卸载设备" aria-label="Permalink to “卸载设备”">​</a></h3><p>使用 umount 命令卸载设备，意味着将所有的“在使用”数据全部写入到文件系统，然后可以安全移除文件系统。请注意，倘若你移除一个没有事先正确卸载的设备，就会有造成设备损坏和数据丢失的风险。</p><p>也就是说，你必须“离开”设备的块设备描述符或者挂载点，才能卸载设备。换言之，你的当前工作目录不能是需要卸载设备的挂载点。否则，系统将返回设备繁忙的提示信息。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Unmount-Device.png" alt="Unmount Device in Linux"></p><p><em>卸载设备</em></p><p>离开需卸载设备的挂载点最简单的方法就是，运行不带任何选项的 cd 命令，这样会回到当前用户的家目录。</p><h3 id="挂载常见的网络文件系统" tabindex="-1">挂载常见的网络文件系统 <a class="header-anchor" href="#挂载常见的网络文件系统" aria-label="Permalink to “挂载常见的网络文件系统”">​</a></h3><p>最常用的两种网络文件系统是 SMB（Server Message Block，服务器消息块）和 NFS（Network File System，网络文件系统）。如果你只向类 Unix 客户端提供共享，用 NFS 就可以了，如果是向 Windows 和其他类 Unix 客户端提供共享服务，就需要用到 Samba 了。</p><p>扩展阅读</p>`,45)),e("ul",null,[e("li",null,[o(a,{href:"http://www.tecmint.com/setup-samba-server-using-tdbsam-backend-on-rhel-centos-6-3-5-8-and-fedora-17-12/"},{default:i(()=>[...t[0]||(t[0]=[n("Setup Samba Server in RHEL/CentOS and Fedora",-1)])]),_:1})]),e("li",null,[o(a,{href:"http://www.tecmint.com/how-to-setup-nfs-server-in-linux/"},{default:i(()=>[...t[1]||(t[1]=[n("Setting up NFS (Network File System) on RHEL/CentOS/Fedora and Debian/Ubuntu",-1)])]),_:1})])]),t[29]||(t[29]=p(`<p>下面的例子中，假设 Samba 和 NFS 已经在地址为 192.168.0.10 的服务器上架设好了（请注意，架设 NFS 服务器也是 LFCS 考试中需要考核的能力，我们会在后边中提到）。</p><h4 id="在-linux-中挂载-samba-共享" tabindex="-1">在 Linux 中挂载 Samba 共享 <a class="header-anchor" href="#在-linux-中挂载-samba-共享" aria-label="Permalink to “在 Linux 中挂载 Samba 共享”">​</a></h4><p>第一步：在 Red Hat 以 Debian 系发行版中安装 samba-client、samba-common 和 cifs-utils 软件包，如下：</p><pre><code># yum update &amp;&amp; yum install samba-client samba-common cifs-utils
# aptitude update &amp;&amp; aptitude install samba-client samba-common cifs-utils
</code></pre><p>然后运行下列命令，查看服务器上可用的 Samba 共享。</p><pre><code># smbclient -L 192.168.0.10
</code></pre><p>并输入远程机器上 root 账户的密码。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-Samba-Share.png" alt="Mount Samba Share in Linux"></p><p><em>挂载 Samba 共享</em></p><p>上图中，已经对可以挂载到我们本地系统上的共享进行高亮显示。你只需要与一个远程服务器上的合法用户名及密码就可以访问共享了。</p><p>第二步：当挂载有密码保护的网络文件系统时候，将你的访问凭证写入到 /etc/fstab 文件中并非明智的选择。你需要将这些信息写入到具有 600 权限的隐藏文件中，像这样：</p><pre><code># mkdir /media/samba
# echo “username=samba_username” &gt; /media/samba/.smbcredentials
# echo “password=samba_password” &gt;&gt; /media/samba/.smbcredentials
# chmod 600 /media/samba/.smbcredentials
</code></pre><p>第三步：然后将下面的内容添加到 /etc/fstab 文件中。</p><pre><code># //192.168.0.10/gacanepa /media/samba cifs credentials=/media/samba/.smbcredentials,defaults 0 0
</code></pre>`,14)),e("p",null,[t[3]||(t[3]=n("第四步：现在可以挂载你的 Samba 共享了。手动挂载（mount ",-1)),o(a,{href:"//192.168.0.10/gacanepa%EF%BC%89%E6%88%96%E8%80%85%E9%87%8D%E5%90%AF%E7%B3%BB%E7%BB%9F%E5%B9%B6%E5%BA%94%E7%94%A8"},{default:i(()=>[...t[2]||(t[2]=[n("//192.168.0.10/gacanepa）或者重启系统并应用",-1)])]),_:1}),t[4]||(t[4]=n(" /etc/fstab 中相应行来用就挂载都可以。",-1))]),t[30]||(t[30]=p(`<p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-Password-Protect-Samba-Share.png" alt="Mount Password Protect Samba Share"></p><p><em>挂载有密码保护的 Samba 共享</em></p><h4 id="在-linux-系统中挂载-nfs-共享" tabindex="-1">在 Linux 系统中挂载 NFS 共享 <a class="header-anchor" href="#在-linux-系统中挂载-nfs-共享" aria-label="Permalink to “在 Linux 系统中挂载 NFS 共享”">​</a></h4><p>第一步：在 Red Hat 以 Debian 系发行版中安装 nfs-common 和 portmap 软件包。如下：</p><pre><code># yum update &amp;&amp; yum install nfs-utils nfs-utils-lib
# aptitude update &amp;&amp; aptitude install nfs-common
</code></pre><p>第二步：为 NFS 共享创建挂载点。</p><pre><code># mkdir /media/nfs
</code></pre><p>第三步：将下面的内容添加到 /etc/fstab 文件中。</p><p>192.168.0.10:/NFS-SHARE /media/nfs nfs defaults 0 0</p><p>第四步：现在可以挂载你的 Samba 共享了。手动挂载（mount 192.168.0.10:/NFS-SHARE）或者重启系统并应用 /etc/fstab 中相应行来用就挂载都可以。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-NFS-Share.png" alt="Mount NFS Share in Linux"></p><p><em>挂载 NFS 共享</em></p><h3 id="永久性挂载文件系统" tabindex="-1">永久性挂载文件系统 <a class="header-anchor" href="#永久性挂载文件系统" aria-label="Permalink to “永久性挂载文件系统”">​</a></h3><p>像前面两个例子那样，/etc/fstab 控制着Linux如何访问硬盘分区及可移动设备。/etc/fstab 由六个字段的内容组成，各个字段之间通过一个空格符或者制表符来分开。井号（#）开始的行只是会被忽略的注释。</p><p>每一行都按照这个格式来写入：</p><pre><code>&lt;file system&gt; &lt;mount point&gt; &lt;type&gt; &lt;options&gt; &lt;dump&gt; &lt;pass&gt;
</code></pre><p>其中：</p><ul><li>&lt;file system&gt;: 第一个字段指定挂载的设备。大多数发行版本都通过分区的标卷（label）或者 UUID 来指定。这样做可以避免分区号改变时带来的错误。</li><li>&lt;mount point&gt;: 第二个字段指定挂载点。</li><li>&lt;type&gt; ：文件系统的类型代码与 mount 命令挂载文件系统时使用的类型代码是一样的。通过 auto 类型代码可以让内核自动检测文件系统，这对于可移动设备来说非常方便。注意，该选项可能不是对所有文件系统可用。</li><li>&lt;options&gt;: 一个（或多个）挂载选项。</li><li>&lt;dump&gt;: 你可能把这个字段设置为 0（否则设置为 1），使得系统启动时禁用 dump 工具（dump 程序曾经是一个常用的备份工具，但现在越来越少用了）对文件系统进行备份。</li><li>&lt;pass&gt;: 这个字段指定启动系统是是否通过 fsck 来检查文件系统的完整性。0 表示 fsck 不对文件系统进行检查。数字越大，优先级越低。因此，根分区（/）最可能使用数字 1，其他所有需要检查的分区则是以数字 2.</li></ul><p><strong>Mount 命令例示</strong></p><ol><li><p>在系统启动时，通过 TECMINT 标卷来挂载文件系统，并具备 rw 和 noexec 属性，你应该将以下语句添加到 /etc/fstab 文件中。</p><p>LABEL=TECMINT /mnt ext4 rw,noexec 0 0</p></li><li><p>若你想在系统启动时挂载 DVD 光驱中的内容，添加以下语句。</p><p>/dev/sr0 /media/cdrom0 iso9660 ro,user,noauto 0 0</p></li></ol><p>其中 /dev/sr0 为你的 DVD 光驱。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>不用怀疑，在命令行中挂载/卸载本地和网络文件系统将是你作为系统管理员的日常责任的一部分。同时，你需要掌握 /etc/fstab 文件的编写。希望本文对你有帮助。随时在下边发表评论（或者提问），并分享本文到你的朋友圈。</p><p>参考链接</p>`,24)),e("ul",null,[e("li",null,[o(a,{href:"https://training.linuxfoundation.org/certification/LFCS"},{default:i(()=>[...t[5]||(t[5]=[n("About the LFCS",-1)])]),_:1})]),e("li",null,[o(a,{href:"https://training.linuxfoundation.org/certification/why-certify-with-us"},{default:i(()=>[...t[6]||(t[6]=[n("Why get a Linux Foundation Certification?",-1)])]),_:1})]),e("li",null,[o(a,{href:"https://identity.linuxfoundation.org/user?destination=pid/1"},{default:i(()=>[...t[7]||(t[7]=[n("Register for the LFCS exam",-1)])]),_:1})])]),t[31]||(t[31]=e("hr",null,null,-1)),e("p",null,[t[9]||(t[9]=n("via: ",-1)),o(a,{href:"http://www.tecmint.com/mount-filesystem-in-linux/"},{default:i(()=>[...t[8]||(t[8]=[n("http://www.tecmint.com/mount-filesystem-in-linux/",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=n("作者：",-1)),o(a,{href:"http://www.tecmint.com/author/gacanepa/"},{default:i(()=>[...t[10]||(t[10]=[n("Gabriel Cánepa",-1)])]),_:1}),t[14]||(t[14]=n(" 译者：",-1)),o(a,{href:"https://github.com/GHLandy"},{default:i(()=>[...t[11]||(t[11]=[n("GHLandy",-1)])]),_:1}),t[15]||(t[15]=n(" 校对：",-1)),o(a,{href:"https://github.com/wxy"},{default:i(()=>[...t[12]||(t[12]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[18]||(t[18]=n("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[16]||(t[16]=[n("LCTT",-1)])]),_:1}),t[19]||(t[19]=n(" 原创翻译，",-1)),o(a,{href:"https://linux.cn/"},{default:i(()=>[...t[17]||(t[17]=[n("Linux中国",-1)])]),_:1}),t[20]||(t[20]=n(" 荣誉推出",-1))])])}const F=l(u,[["render",d]]);export{g as __pageData,F as default};
